"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[9230],{9230(e,n,r){r.d(n,{content:()=>d,description:()=>s,keywords:()=>a,title:()=>t});r(5043);var i=r(579);const t="OECD: Den Prozess bewerten, nicht das Produkt",s="Der OECD Digital Education Outlook 2026 empfiehlt offiziell 'prozessorientierte Bewertung' f\xfcr das KI-Zeitalter. Diese internationale Best\xe4tigung bekr\xe4ftigt, was WhimsyLabs von Anfang an entwickelt hat.",a=["OECD Prozessbewertung","prozessorientierte Benotung","KI Bildungsbewertung","virtuelles Labor Bewertung","technikbasierte Benotung","OECD Digital Education Outlook 2026","formative Bewertung KI","MINT-Bildung","naturwissenschaftliche Bildungsbewertung"],d=(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)("p",{children:['Als die OECD im Januar ihren Digital Education Outlook 2026 ver\xf6ffentlichte, stach eine Empfehlung besonders hervor: Schulen sollten zu einer "prozessorientierten Bewertung" \xfcbergehen. Der 245-seitige Bericht, der internationale Forschung zu generativer KI in der Bildung untersuchte, kam zu dem Schluss, dass "traditionelle Bewertungsmodelle, die sich ausschlie\xdflich auf Endergebnisse konzentrieren, zunehmend unzureichend werden." Stattdessen forderte die OECD die P\xe4dagogen auf, "nicht nur zu bewerten, was Sch\xfcler produzieren, sondern wie sie sich mit dem Lernen auseinandersetzen, um Produkte zu erstellen" (',(0,i.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"OECD, 2026"}),")."]}),(0,i.jsx)("p",{children:"Dies ist keine schrittweise politische Empfehlung. Es stellt einen grundlegenden Wandel dar, wie internationale Organisationen \xfcber Sch\xfclerbewertung in einer Zeit denken, in der KI Aufs\xe4tze generieren, Gleichungen l\xf6sen und sogar Experimente in Sekunden entwerfen kann. F\xfcr uns bei WhimsyLabs bedeutet es auch etwas anderes: internationale Best\xe4tigung eines Ansatzes, den wir seit unserer Gr\xfcndung entwickeln."}),(0,i.jsx)("h2",{children:"Was genau empfiehlt die OECD?"}),(0,i.jsxs)("p",{children:['Der OECD-Bericht ist eindeutig: Wenn KI sofort perfekte Ergebnisse produzieren kann, sagt die Bewertung dieser Ergebnisse fast nichts \xfcber das Lernen der Sch\xfcler aus. Die L\xf6sung besteht laut dem Bericht darin, stattdessen den Prozess zu bewerten. Wie die Europ\xe4ische Plattform f\xfcr Erwachsenenbildung zusammenfasst, schl\xe4gt die OECD vor, dass "anstatt die Abschlussarbeit zu benoten, Lehrer bewerten sollten, wie ein Sch\xfcler mit KI interagiert hat, wie er deren Ausgabe kritisiert hat und wie er seine Ideen im Laufe der Zeit verfeinert hat" (',(0,i.jsx)("a",{href:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026",target:"_blank",rel:"noopener noreferrer",children:"EPALE, 2026"}),")."]}),(0,i.jsx)("p",{children:'Diese Empfehlung stammt aus Forschungsergebnissen, die ein beunruhigendes Paradoxon zeigen: Sch\xfcler, die KI verwenden, schneiden bei unmittelbaren Aufgaben besser ab, aber schlechter, wenn die KI entfernt wird. Der Bericht zitiert Studien, die zeigen, dass KI-unterst\xfctzte Sch\xfcler zwar 48% erfolgreicher bei der Erledigung von Aufgaben waren, ihre Leistung jedoch um 17% sank, wenn sie ohne KI-Unterst\xfctzung getestet wurden. Die OECD nennt dieses Ph\xe4nomen "kognitive Auslagerung", bei der Sch\xfcler die KI das Denken \xfcbernehmen lassen und den mentalen Kampf verpassen, der f\xfcr echtes Lernen notwendig ist.'}),(0,i.jsxs)("p",{children:['Die Besorgnis ist nicht hypothetisch. RTE berichtete \xfcber die Warnung der OECD, dass "KI, wenn sie als Abk\xfcrzung statt als Lernwerkzeug verwendet wird, kognitive Anstrengung verdr\xe4ngen und die F\xe4higkeiten schw\xe4chen kann, die tiefes Lernen unterst\xfctzen." Der Bericht warnt ausdr\xfccklich vor "der Fata Morgana falscher Meisterschaft, bei der die beeindruckenden von KI generierten Ausgaben die Unterentwicklung wesentlicher F\xe4higkeiten verbergen" (',(0,i.jsx)("a",{href:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/",target:"_blank",rel:"noopener noreferrer",children:"RTE, 2026"}),")."]}),(0,i.jsx)("h2",{children:"Warum kann sich die traditionelle Bewertung nicht anpassen?"}),(0,i.jsx)("p",{children:"Das grundlegende Problem bei der traditionellen Bewertung ist, dass sie entwickelt wurde, um Ergebnisse zu messen, als Ergebnisse noch menschliche Anstrengung erforderten. Als ein Sch\xfcler 1990 einen Aufsatz einreichte, korrelierte die Qualit\xe4t dieses Aufsatzes ziemlich gut mit dem Verst\xe4ndnis des Sch\xfclers. Der Sch\xfcler musste das Argument durchdenken, seine Ideen strukturieren und Prosa produzieren, die sein Verst\xe4ndnis widerspiegelte. Das Ergebnis war in einem sinnvollen Sinne ein Beweis f\xfcr den Prozess."}),(0,i.jsx)("p",{children:"Diese Korrelation ist gebrochen. Ein Sch\xfcler kann jetzt eine KI auffordern, in Sekunden einen anspruchsvollen Aufsatz zu generieren, ihn mit kleinen \xc4nderungen einreichen und gute Noten erhalten, obwohl er nichts gelernt hat. Lehrer berichten, dass sie zunehmend Zeit damit verbringen, KI-generierte Arbeit zu erkennen, Zeit, die f\xfcr das eigentliche Unterrichten aufgewendet werden k\xf6nnte."}),(0,i.jsx)("p",{children:"Der OECD-Bericht macht deutlich, dass Erkennung nicht die L\xf6sung ist. KI-generierte Inhalte werden nur schwerer zu identifizieren sein, und das Erkennungs-Wettr\xfcsten lenkt p\xe4dagogische Energie vom Lernen auf die \xdcberwachung um. Die L\xf6sung besteht nicht darin, Betr\xfcger zu fangen, sondern das zu \xe4ndern, was wir bewerten. Wenn wir den Prozess statt des Produkts bewerten, wird KI zum Werkzeug statt zur Bedrohung."}),(0,i.jsx)("h2",{children:"Warum Wissenschaftslabore die perfekte Fallstudie sind"}),(0,i.jsx)("p",{children:"Nirgendwo ist der Unterschied zwischen Prozess und Produkt deutlicher als in der Laborwissenschaft. Wenn ein Sch\xfcler eine Titration durchf\xfchrt und die korrekte Molarit\xe4t angibt, was hat er tats\xe4chlich demonstriert? Er k\xf6nnte systematisch durch das Verfahren argumentiert haben, sorgf\xe4ltige Beobachtungen gemacht und die zugrunde liegende Chemie verstanden haben. Oder er k\xf6nnte einen Nachbarn nach der Antwort gefragt haben, aus dem Laborbericht des letzten Jahres kopiert haben oder einfach Gl\xfcck gehabt haben. Die endg\xfcltige Zahl sagt fast nichts aus."}),(0,i.jsx)("p",{children:"Dieses Problem existierte schon vor KI, aber KI hat es dringend gemacht. Ein Sch\xfcler kann jetzt ChatGPT bitten, einen vollst\xe4ndigen Laborbericht zu schreiben, einschlie\xdflich plausibler Beobachtungen, angemessener Fehleranalyse und gut begr\xfcndeter Schlussfolgerungen, ohne jemals das Equipment zu ber\xfchren. Der Bericht sieht korrekt aus, weil KI synthetisieren kann, wie korrekte Berichte aussehen. Aber der Sch\xfcler hat keine der F\xe4higkeiten entwickelt, die das Labor vermitteln sollte."}),(0,i.jsxs)("p",{children:["Prozessorientierte Bewertung f\xfcr Labore bedeutet zu verfolgen, ",(0,i.jsx)("em",{children:"wie"})," ein Sch\xfcler ein Experiment angeht. Hat er vor dem Beginn eine Hypothese formuliert? Hat er Variablen systematisch oder willk\xfcrlich getestet? Als die Ergebnisse ihn \xfcberraschten, hat er nachgeforscht oder ignoriert? Hat er Daten nachdenklich interpretiert oder voreilige Schl\xfcsse gezogen? Diese Fragen zielen auf das ab, was Laborausbildung tats\xe4chlich entwickeln soll: wissenschaftliches Denken."]}),(0,i.jsx)("h2",{children:"Wie WhimsyLabs Prozessbewertung aufgebaut hat"}),(0,i.jsx)("p",{children:"Bei WhimsyLabs ist prozessorientierte Bewertung keine nachtr\xe4gliche Anpassung als Reaktion auf KI. Es ist, wie wir unsere Plattform von Anfang an konzipiert haben. Unsere virtuellen Labore erfassen jede Aktion, die ein Sch\xfcler durchf\xfchrt: welche Ausr\xfcstung er ausw\xe4hlt, in welcher Reihenfolge er Schritte ausf\xfchrt, wie er auf unerwartete Ergebnisse reagiert und wie sich seine Technik im Laufe der Zeit verbessert. Diese Interaktionsprotokollierung erstellt einen detaillierten Nachweis wissenschaftlichen Denkens in Aktion."}),(0,i.jsxs)("p",{children:[(0,i.jsx)("strong",{children:"Aktionsprotokollierung"})," ist das Fundament. Wenn ein Sch\xfcler die Temperatur misst, erfassen wir nicht nur den Endwert, sondern auch, wann er ihn abgelesen hat, wie viele Messungen er gemacht hat und ob er gewartet hat, bis sich das Thermometer stabilisiert hat. Wenn er eine L\xf6sung pipettiert, verfolgen wir seine Technik, einschlie\xdflich Winkel, Geschwindigkeit und ob er die Spitze vorbefeuchtet hat."]}),(0,i.jsxs)("p",{children:[(0,i.jsx)("strong",{children:"Technikbewertung"})," baut auf der Aktionsprotokollierung auf, um die prozedurale Kompetenz zu bewerten. Unser KI-Tutor WhimsyCat bewertet nicht nur Ergebnisse, sondern auch die Ausf\xfchrung. Ein Sch\xfcler, der den korrekten Endpunkt bei einer Titration durch schlampige Technik erreicht, erh\xe4lt anderes Feedback als einer, dessen Technik pr\xe4zise war, der aber die Molarit\xe4t falsch berechnet hat."]}),(0,i.jsxs)("p",{children:[(0,i.jsx)("strong",{children:"Expertenpfadvergleich"})," setzt das Verhalten der Sch\xfcler in einen Kontext. Wir haben kartiert, wie Expertenwissenschaftler an g\xe4ngige Experimente herangehen, und identifiziert die Entscheidungsb\xe4ume und Probleml\xf6sungsmuster, die geschicktes wissenschaftliches Denken charakterisieren. Wenn der Ansatz eines Sch\xfclers erheblich von Expertenpfaden abweicht, signalisiert dies eine Gelegenheit f\xfcr gezielte Anleitung."]}),(0,i.jsx)("h2",{children:"Was die Forschung unterst\xfctzt"}),(0,i.jsxs)("p",{children:["Die OECD-Empfehlung stimmt mit Jahrzehnten p\xe4dagogischer Forschung \xfcberein. Black und Wiliams wegweisende \xdcberpr\xfcfung von 1998 zeigte, dass formative Bewertung, Feedback w\xe4hrend des Lernens statt danach, erhebliche Lernfortschritte \xfcber alle F\xe4cher und Altersgruppen hinweg erzeugt. Ihre Meta-Analyse fand Effektst\xe4rken zwischen 0,4 und 0,7, gr\xf6\xdfer als fast jede andere p\xe4dagogische Intervention (",(0,i.jsx)("a",{href:"https://journals.sagepub.com/doi/10.3102/00346543068002249",target:"_blank",rel:"noopener noreferrer",children:"Black & Wiliam, 1998"}),")."]}),(0,i.jsx)("p",{children:"Neuere Arbeiten haben sich speziell auf wissenschaftliches Denken konzentriert. Forschung zu virtuellen Laboren hat gezeigt, dass Systeme, die Prozessdaten erfassen, Fehlvorstellungen identifizieren k\xf6nnen, die traditionelle Bewertungen v\xf6llig \xfcbersehen."}),(0,i.jsx)("h2",{children:"Auswirkungen f\xfcr Schulen und Lehrer"}),(0,i.jsx)("p",{children:"Die Empfehlung der OECD hat erhebliche Auswirkungen darauf, wie Schulen die Bewertung angehen. Der Bericht stellt fest, dass KI die f\xfcr administrative Aufgaben aufgewendete Zeit um etwa 31% reduzieren kann, aber nur, wenn Schulen \xfcberdenken, was diese Aufgaben beinhalten. Wenn Lehrer weiterhin Produkte statt Prozesse bewerten, bietet KI keine sinnvolle Hilfe und kann sogar die Arbeitsbelastung durch Erkennungsbem\xfchungen erh\xf6hen."}),(0,i.jsx)("p",{children:"Prozessorientierte Bewertung erfordert andere Infrastruktur. Schulen ben\xf6tigen Lernumgebungen, die Prozessdaten erfassen, was genau das ist, was zweckgebundene Bildungstechnologie bietet. Standardm\xe4\xdfige Chatbots k\xf6nnen das Denken von Sch\xfclern w\xe4hrend eines Chemieexperiments nicht verfolgen. Virtuelle Labore, die f\xfcr die Prozesserfassung konzipiert sind, k\xf6nnen dies."}),(0,i.jsx)("p",{children:'Der \xdcbergang erfordert auch berufliche Weiterentwicklung. Lehrer, die es gewohnt sind, Laborberichte zu korrigieren, ben\xf6tigen Unterst\xfctzung bei der Interpretation von Interaktionsprotokollen, Technikmetriken und Pfadanalysen. Der OECD-Bericht fordert ausdr\xfccklich "neue Kompetenzpfade und Schulungsrahmen", um P\xe4dagogen zu helfen, effektiv mit KI-gest\xfctzten Bewertungssystemen zu arbeiten.'}),(0,i.jsx)("h2",{children:"Die Herausforderung der Umsetzung"}),(0,i.jsx)("p",{children:"Der Wechsel von Ergebnis- zu Prozessbewertung ist nicht einfach. Es erfordert ein Umdenken dessen, was Noten darstellen, das Neugestalten von Rubriken und die Hilfe f\xfcr Sch\xfcler zu verstehen, warum der Weg genauso wichtig ist wie das Ziel. Sch\xfcler, die es gewohnt sind, nur nach Endergebnissen beurteilt zu werden, k\xf6nnten zun\xe4chst Bewertungssysteme ablehnen, die ihren Ansatz bewerten."}),(0,i.jsx)("p",{children:'Es gibt auch Bedenken hinsichtlich der Chancengleichheit. Prozessorientierte Bewertung basiert auf Technologie, die das Verhalten von Sch\xfclern erfasst, was Ger\xe4te, Konnektivit\xe4t und technischen Support erfordert, den nicht alle Schulen derzeit haben. Der OECD-Bericht erkennt dies an und weist auf das Entstehen einer "zweiten digitalen Kluft" hin, die nicht auf dem Zugang, sondern auf der Qualit\xe4t der Nutzung basiert.'}),(0,i.jsx)("p",{children:"WhimsyLabs hat unsere Plattform so konzipiert, dass sie auf Standard-Chromebooks \xfcber typische Schulnetzwerke l\xe4uft, gerade weil Infrastruktureinschr\xe4nkungen real sind. Wir k\xf6nnen die digitale Kluft nicht l\xf6sen, aber wir k\xf6nnen sicherstellen, dass prozessorientierte Bewertung keine spezielle Hardware erfordert, die sich viele Schulen nicht leisten k\xf6nnen."}),(0,i.jsx)("h2",{children:"Was als N\xe4chstes kommt"}),(0,i.jsx)("p",{children:"Die Unterst\xfctzung der OECD f\xfcr prozessorientierte Bewertung ist bedeutsam, weil sie internationale Best\xe4tigung f\xfcr einen Ansatz bietet, der in der p\xe4dagogischen Forschung seit Jahren an Dynamik gewinnt. Schulen und politische Entscheidungstr\xe4ger, die auf ma\xdfgebliche Anleitung gewartet haben, haben sie jetzt. Die Frage ist nicht mehr, ob man zur Prozessbewertung \xfcbergehen soll, sondern wie schnell und effektiv dieser \xdcbergang erfolgen kann."}),(0,i.jsx)("p",{children:"F\xfcr WhimsyLabs ist dieser Moment ermutigend, aber nicht \xfcberraschend. Wir haben unsere Plattform um die Prozessbewertung herum aufgebaut, weil die Forschung sie unterst\xfctzte, weil die Laborausbildung sie erfordert und weil wir glaubten, dass KI schlie\xdflich die reine Ergebnisbewertung unhaltbar machen w\xfcrde. Der OECD-Bericht best\xe4tigt, worauf wir hinarbeiten: eine Zukunft, in der Sch\xfcler nach ihrem Denken bewertet werden, nicht nur nach ihren Antworten."}),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("h2",{children:"Verwandte Artikel"}),(0,i.jsxs)("ul",{children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/process-based-lab-assessment-future",children:"Den Prozess bewerten, nicht die Antwort: Die Zukunft der Laborbewertung"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/ai-text-grading-fails-process-assessment-works",children:"Warum KI-Textbewertung versagt und Prozessbewertung funktioniert"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/oecd-ai-learning-paradox-virtual-labs",children:"Das OECD KI-Lernparadoxon und was es f\xfcr virtuelle Labore bedeutet"})})]})]}),(0,i.jsxs)("div",{className:"references-section",children:[(0,i.jsx)("h3",{children:"Referenzen"}),(0,i.jsxs)("ul",{className:"references-list",children:[(0,i.jsxs)("li",{children:["Black, P., & Wiliam, D. (1998). Assessment and classroom learning. ",(0,i.jsx)("em",{children:"Assessment in Education: Principles, Policy & Practice, 5"}),"(1), 7-74."," ",(0,i.jsx)("a",{href:"https://journals.sagepub.com/doi/10.3102/00346543068002249",target:"_blank",rel:"noopener noreferrer",children:"https://doi.org/10.3102/00346543068002249"})]},"ref-1"),(0,i.jsxs)("li",{children:["European Platform for Adult Learning in Europe (EPALE). (2026). The Future of Learning: Key Takeaways from the OECD Digital Education Outlook 2026."," ",(0,i.jsx)("a",{href:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026",target:"_blank",rel:"noopener noreferrer",children:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026"})]},"ref-2"),(0,i.jsxs)("li",{children:["OECD. (2026). OECD Digital Education Outlook 2026: Exploring Effective Uses of Generative AI in Education. OECD Publishing."," ",(0,i.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html"})]},"ref-3"),(0,i.jsxs)("li",{children:["O'Kelly, E. (2026). Warning over uncritical AI use in education. RTE News."," ",(0,i.jsx)("a",{href:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/",target:"_blank",rel:"noopener noreferrer",children:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/"})]},"ref-4")]})]})]})}}]);
